--------------------------------------------------------------------------------
-- TOP_tb.vhd
-- Testbench for TOP (AXI wrapper around extractor_top).
--
-- Vectors: generated by top_tb_generator.py (which imports the validated
-- golden model from extractor_top_generator.py). Two frames with different
-- dimensions; frame 1 is the exact validated extractor_top vector set.
--
-- Test sequence (sequencer process):
--   T1  Register liveness: ID, THRESH, STATUS readback after reset
--   T2  Config rejection: WIDTH=0 (reset default), WIDTH that aliases after
--       truncation to COORD_WIDTH bits, HEIGHT < PATCH_SIZE -- each must set
--       STATUS.cfg_error and must NOT raise busy
--   T3  Frame 1 (full size = G_MAX_WIDTH): complete keypoint check against
--       golden data, sentinel + tlast, KPCOUNT, DROPCNT=0, overflow=0,
--       done persists until next start, cfg_error cleared by valid start
--   T4  Frame 2 (smaller dims, no DUT reconfig beyond the WIDTH/HEIGHT
--       registers): the per-pyramid-level production pattern
--   T5  Soft reset recovery: start frame, stream 1/3 of it WITHOUT tlast
--       (wedged mid-frame), soft reset, verify STATUS/KPCOUNT cleared and
--       no stray beats leak afterward
--   T6  Recovery frame: rerun frame 2 WITHOUT rewriting WIDTH/HEIGHT
--       (config registers must survive soft reset), full keypoint check
--   T7  (production config ONLY) Dense frame, 1200 keypoints: both FIFO
--       pointer sets wrap at the SHIPPED depths (corner FIFO 512 wraps
--       twice, output FIFO 1024 wraps once) while burst occupancy stays
--       ~50 -- so the run remains drop-free and the exact-sequence golden
--       check stays valid. Skipped in the stall config, where those depths
--       do not exist (wrap there is already exercised at 64/128).
--
-- Two run configurations (TB generic G_STALL_TEST):
--   false: production FIFO generics, m_axis_tready tied high.
--       This is the path the original sentinel-handshake bug lived on.
--   true: shrunk FIFOs (core 64 / gap 80 / kp 128) so prog_full is reachable,
--       plus randomized m_axis_tready with short gaps and long (8000-cycle)
--       stalls. Same checks must all still pass; pixel-side backpressure
--       engagement is reported via the bp_cycles counter. This converts the
--       deferred TREADY-stall verification (F.6) from analytical to simulated.
--
--   vsim -gG_STALL_TEST=false work.top_tb -do "run -all"  -- production config
--   vsim -gG_STALL_TEST=true  work.top_tb -do "run -all"  -- stall config
--
-- Score configs (G_SCORE_TYPE, forwarded to the DUT; OpenCV enum 0=HARRIS,
-- 1=FAST): the FAST default checks against top_expected_f*.txt; -gG_SCORE_TYPE=0
-- selects the Harris DUT build AND the top_expected_f*_harris.txt goldens (same
-- corner set -- only the 32-bit response column differs).
--
-- NOT covered here (hardware-side, by design): real AXI DMA behavior
-- (descriptors, MM2S tkeep semantics, S2MM completion), udmabuf/UIO driver
-- path, timing closure.
--------------------------------------------------------------------------------

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use ieee.math_real.all;
use std.textio.all;
use ieee.std_logic_textio.all;

use work.feature_pkg.all;
use work.top_test_params_pkg.all;

entity TOP_tb is
    generic (
        G_STALL_TEST : boolean := false;
        G_SCORE_TYPE : natural := 1     -- 0 = HARRIS_SCORE, 1 = FAST_SCORE
    );
end entity;

architecture sim of TOP_tb is
    constant CLK_PERIOD   : time    := 4 ns;
    constant CORDIC_WIDTH : natural := 24;
    constant KP_WIDTH     : natural := 128;

    -- Stall config shrinks the FIFOs so prog_full is actually reachable:
    -- threshold = 128 - 80 = 48 buffered keypoints during a long stall.
    function pick(c : boolean; a, b : positive) return positive is
    begin
        if c then return a; else return b; end if;
    end function;

    constant CFG_KP_FIFO_DEPTH   : positive := pick(G_STALL_TEST, 128, 1024);
    constant CFG_PROG_FULL_GAP   : positive := pick(G_STALL_TEST,  80,  530);
    constant CFG_CORE_FIFO_DEPTH : positive := pick(G_STALL_TEST,  64,  512);

    -- Register byte offsets (match TOP's OFF_* word indices * 4)
    constant A_CTRL    : natural := 16#00#;
    constant A_STATUS  : natural := 16#04#;
    constant A_WIDTH   : natural := 16#08#;
    constant A_HEIGHT  : natural := 16#0C#;
    constant A_THRESH  : natural := 16#10#;
    constant A_KPCOUNT : natural := 16#14#;
    constant A_DROPCNT : natural := 16#18#;
    constant A_ID      : natural := 16#1C#;
    constant A_CELLDIM : natural := 16#20#;   -- [15:0]=wCell [31:16]=hCell (strict-cell gate)
    constant A_CELLNUM : natural := 16#24#;   -- [15:0]=nCols [31:16]=nRows (strict-cell gate)
    constant A_SUPPCNT : natural := 16#28#;   -- RO gate-suppressed corner count

    -- DUT ports
    signal aclk    : std_logic := '0';
    signal aresetn : std_logic := '0';

    signal s_axis_tdata  : std_logic_vector(PIXEL_WIDTH-1 downto 0) := (others => '0');
    signal s_axis_tkeep  : std_logic_vector(0 downto 0)             := "1";
    signal s_axis_tvalid : std_logic := '0';
    signal s_axis_tready : std_logic;
    signal s_axis_tlast  : std_logic := '0';

    signal m_axis_tdata  : std_logic_vector(KP_WIDTH-1 downto 0);
    signal m_axis_tkeep  : std_logic_vector(KP_WIDTH/8-1 downto 0);
    signal m_axis_tvalid : std_logic;
    signal m_axis_tready : std_logic := '1';
    signal m_axis_tlast  : std_logic;

    signal s_axi_awaddr  : std_logic_vector(5 downto 0)  := (others => '0');
    signal s_axi_awprot  : std_logic_vector(2 downto 0)  := "000";
    signal s_axi_awvalid : std_logic := '0';
    signal s_axi_awready : std_logic;
    signal s_axi_wdata   : std_logic_vector(31 downto 0) := (others => '0');
    signal s_axi_wstrb   : std_logic_vector(3 downto 0)  := "1111";
    signal s_axi_wvalid  : std_logic := '0';
    signal s_axi_wready  : std_logic;
    signal s_axi_bresp   : std_logic_vector(1 downto 0);
    signal s_axi_bvalid  : std_logic;
    signal s_axi_bready  : std_logic := '1';
    signal s_axi_araddr  : std_logic_vector(5 downto 0)  := (others => '0');
    signal s_axi_arprot  : std_logic_vector(2 downto 0)  := "000";
    signal s_axi_arvalid : std_logic := '0';
    signal s_axi_arready : std_logic;
    signal s_axi_rdata   : std_logic_vector(31 downto 0);
    signal s_axi_rresp   : std_logic_vector(1 downto 0);
    signal s_axi_rvalid  : std_logic;
    signal s_axi_rready  : std_logic := '1';

    ----------------------------------------------------------------------------
    -- TB plumbing
    ----------------------------------------------------------------------------
    -- Sequencer -> producer: which pixel file, how many beats, tlast or not.
    type stream_desc_t is record
        file_id    : natural;   -- 1 or 2
        n_pixels   : natural;
        send_tlast : boolean;
    end record;
    signal stream_desc     : stream_desc_t := (1, 0, true);
    signal stream_go_cnt   : natural := 0;  -- sequencer increments
    signal stream_done_cnt : natural := 0;  -- producer increments

    -- Sequencer -> checker: what the beat stream must contain right now.
    --   CHK_IDLE    : any beat is an error (between frames, after reset)
    --   CHK_FRAME   : compare against expected file chk_file_id
    --   CHK_DISCARD : swallow beats silently (aborted frame in T5)
    type chk_mode_t is (CHK_IDLE, CHK_FRAME, CHK_DISCARD);
    signal chk_mode       : chk_mode_t := CHK_IDLE;
    signal chk_file_id    : natural := 1;
    signal chk_n_expected : natural := 0;
    signal chk_go_cnt     : natural := 0;   -- sequencer increments to arm a frame check
    signal chk_done_cnt   : natural := 0;   -- checker increments after the sentinel
    signal chk_errors     : natural := 0;   -- mirrored from the checker's count
    signal chk_max_diff   : natural := 0;   -- worst angle diff over all frames

    signal bp_cycles : natural := 0;        -- pixel backpressure (prog_full engaged)
    signal pix_acc   : natural := 0;        -- accepted pixels (stall-test scheduling)
    signal sim_done  : boolean := false;

    function pix_filename(id : natural) return string is
    begin
        if    id = 1 then return F1_PIXELS_FILE;
        elsif id = 2 then return F2_PIXELS_FILE;
        else              return F3_PIXELS_FILE;
        end if;
    end function;

    function exp_filename(id : natural) return string is
    begin
        if G_SCORE_TYPE = 0 then
            if    id = 1 then return F1_EXPECTED_HARRIS_FILE;
            elsif id = 2 then return F2_EXPECTED_HARRIS_FILE;
            else              return F3_EXPECTED_HARRIS_FILE;
            end if;
        else
            if    id = 1 then return F1_EXPECTED_FILE;
            elsif id = 2 then return F2_EXPECTED_FILE;
            else              return F3_EXPECTED_FILE;
            end if;
        end if;
    end function;

    -- Shortest-path angular distance (handles +-pi wrap); same as extractor_top_tb.
    function angle_diff(a, b : signed) return natural is
        constant FULL_CIRCLE : integer := 2**(CORDIC_WIDTH-1);
        variable d : integer;
    begin
        d := abs(to_integer(a) - to_integer(b));
        if d > FULL_CIRCLE / 2 then
            d := FULL_CIRCLE - d;
        end if;
        return d;
    end function;

begin

    dut : entity work.TOP
        generic map (
            G_KP_WIDTH        => KP_WIDTH,
            G_KP_FIFO_DEPTH   => CFG_KP_FIFO_DEPTH,
            G_IDLE_GAP        => 512,
            G_MAX_WIDTH       => F1_WIDTH,          -- frame 1 is the largest level
            G_THRESH_PERM     => TOP_TB_TH_PERM,
            G_THRESH_STRICT   => TOP_TB_TH_STRICT,
            G_SCORE_TYPE      => G_SCORE_TYPE,
            G_CORE_FIFO_DEPTH => CFG_CORE_FIFO_DEPTH,
            G_PROG_FULL_GAP   => CFG_PROG_FULL_GAP
        )
        port map (
            aclk          => aclk,
            aresetn       => aresetn,
            s_axis_tdata  => s_axis_tdata,
            s_axis_tkeep  => s_axis_tkeep,
            s_axis_tvalid => s_axis_tvalid,
            s_axis_tready => s_axis_tready,
            s_axis_tlast  => s_axis_tlast,
            m_axis_tdata  => m_axis_tdata,
            m_axis_tkeep  => m_axis_tkeep,
            m_axis_tvalid => m_axis_tvalid,
            m_axis_tready => m_axis_tready,
            m_axis_tlast  => m_axis_tlast,
            s_axi_awaddr  => s_axi_awaddr,
            s_axi_awprot  => s_axi_awprot,
            s_axi_awvalid => s_axi_awvalid,
            s_axi_awready => s_axi_awready,
            s_axi_wdata   => s_axi_wdata,
            s_axi_wstrb   => s_axi_wstrb,
            s_axi_wvalid  => s_axi_wvalid,
            s_axi_wready  => s_axi_wready,
            s_axi_bresp   => s_axi_bresp,
            s_axi_bvalid  => s_axi_bvalid,
            s_axi_bready  => s_axi_bready,
            s_axi_araddr  => s_axi_araddr,
            s_axi_arprot  => s_axi_arprot,
            s_axi_arvalid => s_axi_arvalid,
            s_axi_arready => s_axi_arready,
            s_axi_rdata   => s_axi_rdata,
            s_axi_rresp   => s_axi_rresp,
            s_axi_rvalid  => s_axi_rvalid,
            s_axi_rready  => s_axi_rready
        );

    aclk <= not aclk after CLK_PERIOD/2 when not sim_done else '0';

    rst_proc : process
    begin
        aresetn <= '0';
        wait for 5 * CLK_PERIOD;
        aresetn <= '1';
        wait;
    end process;

    -- ============================================================
    -- m_axis_tready generation.
    -- Normal run: tied high (the path the original sentinel bug lived on).
    -- Stall run: random short gaps (handshake fuzz, fixed seeds ->
    -- reproducible) PLUS a deterministic 8000-cycle stall every 9000
    -- accepted pixels. The periodic stalls are guaranteed to overlap the
    -- keypoint-producing square bands, so the output FIFO crosses the
    -- prog_full threshold (DEPTH-GAP = 48 in this config) and pixel tready
    -- is withdrawn mid-frame -- the full F.6 backpressure chain. The frame
    -- completeness check then proves the throttling is loss-free.
    -- ============================================================
    tready_gen : process
        variable s1        : positive := 17;
        variable s2        : positive := 311;
        variable r         : real;
        variable n         : natural;
        variable next_mark : natural := 9000;
    begin
        m_axis_tready <= '1';
        if not G_STALL_TEST then
            wait;
        end if;
        loop
            wait until rising_edge(aclk);
            if pix_acc >= next_mark then
                next_mark := next_mark + 9000;
                m_axis_tready <= '0';               -- long stall: forces prog_full
                for i in 1 to 8000 loop
                    wait until rising_edge(aclk);
                end loop;
                m_axis_tready <= '1';
            else
                uniform(s1, s2, r);
                if r < 0.20 then
                    m_axis_tready <= '0';           -- short gap, 1..8 cycles
                    uniform(s1, s2, r);
                    n := 1 + natural(r * 7.0);
                    for i in 1 to n loop
                        wait until rising_edge(aclk);
                    end loop;
                    m_axis_tready <= '1';
                end if;
            end if;
        end loop;
    end process;

    -- Pixel-side backpressure observability: nonzero in the stall run means
    -- prog_full actually engaged (tready withdrawn mid-frame) and the frame
    -- still checked complete -> loss-free throttling demonstrated.
    bp_mon : process(aclk)
    begin
        if rising_edge(aclk) then
            if s_axis_tvalid = '1' and s_axis_tready = '0' then
                bp_cycles <= bp_cycles + 1;
            end if;
            if s_axis_tvalid = '1' and s_axis_tready = '1' then
                pix_acc <= pix_acc + 1;     -- accepted-pixel count (stall scheduling)
            end if;
        end if;
    end process;

    -- ============================================================
    -- Producer: descriptor-driven AXI-Stream pixel source.
    -- Honors tready (proper AXIS master). T5 sends a partial frame
    -- with no tlast to wedge the DUT mid-frame on purpose.
    -- ============================================================
    producer : process
        file     pf       : text;
        variable line_in  : line;
        variable pix_v    : std_logic_vector(7 downto 0);
        variable v_served : natural := 0;
    begin
        loop
            wait until stream_go_cnt /= v_served;
            v_served := stream_go_cnt;

            file_open(pf, pix_filename(stream_desc.file_id), read_mode);
            for p in 0 to stream_desc.n_pixels - 1 loop
                readline(pf, line_in);
                hread(line_in, pix_v);
                s_axis_tdata  <= pix_v;
                s_axis_tvalid <= '1';
                if stream_desc.send_tlast and p = stream_desc.n_pixels - 1 then
                    s_axis_tlast <= '1';
                else
                    s_axis_tlast <= '0';
                end if;
                loop
                    wait until rising_edge(aclk);
                    exit when s_axis_tready = '1';
                end loop;
            end loop;
            s_axis_tvalid <= '0';
            s_axis_tlast  <= '0';
            file_close(pf);

            stream_done_cnt <= stream_done_cnt + 1;
        end loop;
    end process;

    -- ============================================================
    -- Checker: AXI-Stream keypoint sink.
    -- CHK_FRAME: every accepted beat is unpacked and compared against the
    -- expected file -- coordinates/score/flags exact, angle within the
    -- per-vector CORDIC tolerance, all pad/reserved bits zero, tlast only
    -- on the EOF sentinel, sentinel exactly after N real beats.
    -- CHK_IDLE: any beat at all is an error (stale-FIFO leak detector).
    -- ============================================================
    checker : process
        file     ef       : text;
        variable line_in  : line;
        variable v_served : natural := 0;
        variable v_k      : natural := 0;
        variable v_err    : natural := 0;
        variable v_maxd   : natural := 0;
        variable v_fmaxd  : natural := 0;

        variable ex, ey, es, eb, estrict, etol : integer;
        variable eangle_v, em10_v, em01_v : std_logic_vector(CORDIC_WIDTH-1 downto 0);
        variable eangle : signed(CORDIC_WIDTH-1 downto 0);
        variable eresp_v : std_logic_vector(31 downto 0);
        variable eresp   : signed(31 downto 0);

        variable beat    : std_logic_vector(KP_WIDTH-1 downto 0);
        variable hwangle : signed(CORDIC_WIDTH-1 downto 0);
        variable diff    : natural;

        procedure err(msg : string) is
        begin
            report "CHECKER: " & msg severity error;
            v_err := v_err + 1;
        end procedure;
    begin
        loop
            wait until rising_edge(aclk);

            -- Sequencer armed a new frame check (always before enabling the DUT,
            -- so this can never race an in-flight beat).
            if chk_go_cnt /= v_served then
                v_served := chk_go_cnt;
                file_open(ef, exp_filename(chk_file_id), read_mode);
                v_k     := 0;
                v_fmaxd := 0;
            end if;

            if m_axis_tvalid = '1' and m_axis_tready = '1' then
                beat := m_axis_tdata;

                case chk_mode is
                    when CHK_DISCARD =>
                        null;

                    when CHK_IDLE =>
                        err("beat outside any frame (stale FIFO leak?), word0=0x"
                            & to_hstring(beat(31 downto 0)));

                    when CHK_FRAME =>
                        if beat(127 downto 96) = x"FFFFFFFF" then
                            -- EOF sentinel
                            if m_axis_tlast /= '1' then
                                err("sentinel without tlast");
                            end if;
                            if unsigned(beat(95 downto 0)) /= 0 then
                                err("sentinel low words not zero");
                            end if;
                            if v_k /= chk_n_expected then
                                err("sentinel after " & to_string(v_k) &
                                    " keypoints, expected " & to_string(chk_n_expected));
                            end if;
                            report "Frame check (file " & to_string(chk_file_id) &
                                   "): " & to_string(v_k) & " keypoints, max angle diff "
                                   & to_string(v_fmaxd);
                            file_close(ef);
                            if v_fmaxd > v_maxd then
                                v_maxd := v_fmaxd;
                            end if;
                            chk_max_diff <= v_maxd;
                            chk_errors   <= v_err;
                            chk_done_cnt <= chk_done_cnt + 1;
                        else
                            -- real keypoint beat
                            if m_axis_tlast = '1' then
                                err("tlast on a non-sentinel beat (kp " & to_string(v_k) & ")");
                            end if;
                            if v_k >= chk_n_expected then
                                err("more keypoints than expected (kp " & to_string(v_k) &
                                    "), word0=0x" & to_hstring(beat(31 downto 0)));
                            else
                                readline(ef, line_in);
                                read(line_in, ex);
                                read(line_in, ey);
                                read(line_in, es);
                                read(line_in, eb);
                                read(line_in, estrict);
                                hread(line_in, eangle_v); eangle := signed(eangle_v);
                                read(line_in, etol);
                                hread(line_in, em10_v);
                                hread(line_in, em01_v);
                                hread(line_in, eresp_v); eresp := signed(eresp_v);

                                if to_integer(unsigned(beat(10 downto 0))) /= ex then
                                    err("kp " & to_string(v_k) & ": x = " &
                                        to_string(to_integer(unsigned(beat(10 downto 0)))) &
                                        ", expected " & to_string(ex));
                                end if;
                                if to_integer(unsigned(beat(26 downto 16))) /= ey then
                                    err("kp " & to_string(v_k) & ": y = " &
                                        to_string(to_integer(unsigned(beat(26 downto 16)))) &
                                        ", expected " & to_string(ey));
                                end if;
                                -- packing v3: word1 = the full 32-bit response
                                -- (FAST score zero-extended or Harris response)
                                if signed(beat(63 downto 32)) /= eresp then
                                    err("kp " & to_string(v_k) & " (" & to_string(ex) & "," &
                                        to_string(ey) & "): response = " &
                                        to_string(to_integer(signed(beat(63 downto 32)))) &
                                        ", expected " & to_string(to_integer(eresp)));
                                end if;
                                if (beat(88) = '1') /= (eb = 1) then
                                    err("kp " & to_string(v_k) & ": is_brighter mismatch");
                                end if;
                                if (beat(89) = '1') /= (estrict = 1) then
                                    err("kp " & to_string(v_k) & " (" & to_string(ex) & "," &
                                        to_string(ey) & ", score=" & to_string(es) &
                                        "): passed_strict mismatch");
                                end if;

                                -- pad / reserved contract (v3: angle is 24b raw in
                                -- word2, flags at 88/89, 95:90 reserved zero)
                                if beat(15 downto 11) /= "00000"
                                   or beat(31 downto 27) /= "00000"
                                   or unsigned(beat(95 downto 90)) /= 0 then
                                    err("kp " & to_string(v_k) & ": nonzero pad/reserved bits");
                                end if;
                                hwangle := signed(beat(87 downto 64));
                                if beat(127 downto 96) /= x"00000000" then
                                    err("kp " & to_string(v_k) & ": word3 not zero on real beat");
                                end if;

                                diff := angle_diff(hwangle, eangle);
                                if diff > v_fmaxd then
                                    v_fmaxd := diff;
                                end if;
                                if diff > etol then
                                    err("kp " & to_string(v_k) & " (" & to_string(ex) & "," &
                                        to_string(ey) & "): angle diff " & to_string(diff) &
                                        " exceeds tol " & to_string(etol) &
                                        " (got " & to_string(to_integer(hwangle)) &
                                        ", exp " & to_string(to_integer(eangle)) & ")");
                                end if;
                            end if;
                            v_k := v_k + 1;
                            chk_errors <= v_err;
                        end if;
                end case;
            end if;
        end loop;
    end process;

    -- ============================================================
    -- Sequencer: AXI-Lite master + test program.
    -- ============================================================
    sequencer : process
        variable v_serr : natural := 0;
        variable d      : std_logic_vector(31 downto 0);

        procedure tick(n : natural := 1) is
        begin
            for i in 1 to n loop
                wait until rising_edge(aclk);
            end loop;
        end procedure;

        procedure chk(cond : boolean; msg : string) is
        begin
            if not cond then
                report "SEQ: " & msg severity error;
                v_serr := v_serr + 1;
            end if;
        end procedure;

        -- AXI4-Lite write: address+data presented together, deasserted after
        -- the cycle where both readies were sampled high (the cycle the DUT's
        -- register write executes), then wait for the write response.
        procedure axil_write(addr : natural; data : std_logic_vector(31 downto 0)) is
        begin
            s_axi_awaddr  <= std_logic_vector(to_unsigned(addr, 6));
            s_axi_wdata   <= data;
            s_axi_awvalid <= '1';
            s_axi_wvalid  <= '1';
            loop
                wait until rising_edge(aclk);
                exit when s_axi_awready = '1' and s_axi_wready = '1';
            end loop;
            s_axi_awvalid <= '0';
            s_axi_wvalid  <= '0';
            loop
                wait until rising_edge(aclk);
                exit when s_axi_bvalid = '1';
            end loop;
        end procedure;

        procedure axil_read(addr : natural; data : out std_logic_vector(31 downto 0)) is
        begin
            s_axi_araddr  <= std_logic_vector(to_unsigned(addr, 6));
            s_axi_arvalid <= '1';
            loop
                wait until rising_edge(aclk);
                exit when s_axi_arready = '1';
            end loop;
            s_axi_arvalid <= '0';
            loop
                wait until rising_edge(aclk);
                exit when s_axi_rvalid = '1';
            end loop;
            data := s_axi_rdata;
        end procedure;

        procedure poll_done is
            variable s : std_logic_vector(31 downto 0);
        begin
            loop
                axil_read(A_STATUS, s);
                exit when s(1) = '1';
            end loop;
        end procedure;

        -- Enable with an (invalid) configuration: busy must NOT rise,
        -- cfg_error MUST. Leaves CTRL cleared.
        procedure expect_cfg_reject(msg : string) is
            variable s : std_logic_vector(31 downto 0);
        begin
            axil_write(A_CTRL, x"00000001");
            tick(6);
            axil_read(A_STATUS, s);
            chk(s(0) = '0', "busy rose on invalid config: " & msg);
            chk(s(3) = '1', "cfg_error not set: " & msg);
            axil_write(A_CTRL, x"00000000");
            tick(2);
        end procedure;

        -- One complete checked frame: arm checker, configure, enable, stream,
        -- wait for done, verify counters and status, ack.
        procedure run_checked_frame(fid, fw, fh, fn : natural;
                                    fnsupp : natural;
                                    fwc : natural := 0; fhc : natural := 0;
                                    fnc : natural := 0; fnr : natural := 0;
                                    write_dims : boolean := true) is
            variable s : std_logic_vector(31 downto 0);
        begin
            chk_mode       <= CHK_FRAME;
            chk_file_id    <= fid;
            chk_n_expected <= fn;
            chk_go_cnt     <= chk_go_cnt + 1;
            tick(2);

            if write_dims then
                axil_write(A_WIDTH,  std_logic_vector(to_unsigned(fw, 32)));
                axil_write(A_HEIGHT, std_logic_vector(to_unsigned(fh, 32)));
                -- Strict-cell gate geometry: CELLDIM = hCell:wCell, CELLNUM = nRows:nCols.
                axil_write(A_CELLDIM, std_logic_vector(to_unsigned(fhc, 16)) &
                                      std_logic_vector(to_unsigned(fwc, 16)));
                axil_write(A_CELLNUM, std_logic_vector(to_unsigned(fnr, 16)) &
                                      std_logic_vector(to_unsigned(fnc, 16)));
            end if;
            axil_write(A_CTRL, x"00000001");
            tick(4);
            axil_read(A_STATUS, s);
            chk(s(0) = '1', "busy not set after valid start");
            chk(s(3) = '0', "cfg_error not cleared by valid start");

            stream_desc   <= (file_id => fid, n_pixels => fw * fh, send_tlast => true);
            stream_go_cnt <= stream_go_cnt + 1;
            tick(1);
            wait until stream_done_cnt = stream_go_cnt;

            poll_done;
            if chk_done_cnt /= chk_go_cnt then
                wait until chk_done_cnt = chk_go_cnt;
            end if;

            axil_read(A_KPCOUNT, s);
            chk(to_integer(unsigned(s)) = fn,
                "KPCOUNT = " & to_string(to_integer(unsigned(s))) &
                ", expected " & to_string(fn));
            axil_read(A_DROPCNT, s);
            chk(unsigned(s) = 0,
                "DROPCNT = " & to_string(to_integer(unsigned(s))) & ", expected 0");
            axil_read(A_SUPPCNT, s);
            chk(to_integer(unsigned(s)) = fnsupp,
                "SUPPCNT = " & to_string(to_integer(unsigned(s))) &
                ", expected " & to_string(fnsupp));
            axil_read(A_STATUS, s);
            chk(s(2) = '0', "overflow flag set");

            axil_write(A_CTRL, x"00000000");   -- ack done
            tick(4);
            axil_read(A_STATUS, s);
            chk(s(0) = '0', "busy still set after ack");
            chk(s(1) = '1', "done should persist until the next start");

            chk_mode <= CHK_IDLE;
            tick(2);
        end procedure;

    begin
        wait until aresetn = '1';
        tick(4);

        ------------------------------------------------------------------
        -- T1: register liveness
        ------------------------------------------------------------------
        axil_read(A_ID, d);
        chk(d = x"C0DE0003", "ID readback: got 0x" & to_hstring(d));
        axil_read(A_THRESH, d);
        chk(to_integer(unsigned(d)) =
                G_SCORE_TYPE * 65536 + TOP_TB_TH_STRICT * 256 + TOP_TB_TH_PERM,
            "THRESH readback (incl. [16]=score type): got 0x" & to_hstring(d));
        axil_read(A_STATUS, d);
        chk(d = x"00000000", "STATUS not clean after reset: 0x" & to_hstring(d));
        report "T1 register liveness done";

        ------------------------------------------------------------------
        -- T2: config rejection (WIDTH still at its reset default of 0!)
        ------------------------------------------------------------------
        expect_cfg_reject("WIDTH=0 (unprogrammed reset default)");

        -- 0x00010100: lower COORD_WIDTH bits look like a valid 256, but the
        -- full 32-bit value would alias after truncation -> must reject.
        axil_write(A_WIDTH,  x"00010100");
        axil_write(A_HEIGHT, std_logic_vector(to_unsigned(F1_HEIGHT, 32)));
        expect_cfg_reject("WIDTH aliasing after COORD_WIDTH truncation");

        axil_write(A_WIDTH,  std_logic_vector(to_unsigned(F1_WIDTH, 32)));
        axil_write(A_HEIGHT, std_logic_vector(to_unsigned(16, 32)));
        expect_cfg_reject("HEIGHT < PATCH_SIZE");
        report "T2 config rejection done";

        ------------------------------------------------------------------
        -- T3: frame 1, full size (also proves cfg_error clears on valid start)
        ------------------------------------------------------------------
        run_checked_frame(1, F1_WIDTH, F1_HEIGHT, F1_N_EXPECTED, F1_N_SUPPRESSED,
                          F1_WCELL, F1_HCELL, F1_NCOLS, F1_NROWS);
        report "T3 frame 1 done";

        ------------------------------------------------------------------
        -- T4: frame 2, smaller dims -- the per-pyramid-level pattern
        ------------------------------------------------------------------
        run_checked_frame(2, F2_WIDTH, F2_HEIGHT, F2_N_EXPECTED, F2_N_SUPPRESSED,
                          F2_WCELL, F2_HCELL, F2_NCOLS, F2_NROWS);
        report "T4 frame 2 (runtime resize) done";

        ------------------------------------------------------------------
        -- T5: wedge mid-frame (partial stream, NO tlast), then soft reset
        ------------------------------------------------------------------
        chk_mode <= CHK_DISCARD;
        tick(2);
        axil_write(A_WIDTH,  std_logic_vector(to_unsigned(F2_WIDTH, 32)));
        axil_write(A_HEIGHT, std_logic_vector(to_unsigned(F2_HEIGHT, 32)));
        axil_write(A_CTRL, x"00000001");
        tick(4);
        axil_read(A_STATUS, d);
        chk(d(0) = '1', "T5: busy not set");

        stream_desc   <= (file_id => 2, n_pixels => (F2_WIDTH * F2_HEIGHT) / 3,
                          send_tlast => false);
        stream_go_cnt <= stream_go_cnt + 1;
        tick(1);
        wait until stream_done_cnt = stream_go_cnt;
        tick(3000);   -- let pending corners drain and transfer (all discarded)

        axil_write(A_CTRL, x"00000002");   -- soft reset (write 1...)
        tick(6);
        axil_write(A_CTRL, x"00000000");   -- (...then 0; not self-clearing)
        tick(6);
        axil_read(A_STATUS, d);
        chk(d(3 downto 0) = "0000",
            "T5: STATUS not clean after soft reset: 0x" & to_hstring(d));
        axil_read(A_KPCOUNT, d);
        chk(unsigned(d) = 0, "T5: KPCOUNT not cleared by soft reset");

        -- Stray-beat window: FIFO was cleared, so nothing may arrive now.
        chk_mode <= CHK_IDLE;
        tick(400);
        report "T5 soft reset recovery done";

        ------------------------------------------------------------------
        -- T6: clean frame WITHOUT rewriting dims (they must survive the
        -- soft reset) -- proves full recovery from the wedged state
        ------------------------------------------------------------------
        run_checked_frame(2, F2_WIDTH, F2_HEIGHT, F2_N_EXPECTED, F2_N_SUPPRESSED,
                          write_dims => false);
        report "T6 post-reset recovery frame done";

        ------------------------------------------------------------------
        -- T7 (production config only): dense frame -- pointer wrap at the
        -- shipped depths. F3 has 1200 keypoints: corner-FIFO wr/rd pointers
        -- wrap their 512 modulus twice, output-FIFO pointers wrap 1024 once.
        -- Burst occupancy stays ~50, so DROPCNT must remain 0. In the stall
        -- config those depths do not exist and the dense burst would crowd
        -- the 64-deep corner FIFO, so the test is skipped there.
        ------------------------------------------------------------------
        if not G_STALL_TEST then
            run_checked_frame(3, F3_WIDTH, F3_HEIGHT, F3_N_EXPECTED, F3_N_SUPPRESSED,
                              F3_WCELL, F3_HCELL, F3_NCOLS, F3_NROWS);
            report "T7 dense frame (pointer wrap at shipped FIFO depths) done";
        else
            report "T7 skipped (stall config: wrap exercised at 64/128 instead)";
        end if;

        ------------------------------------------------------------------
        -- Summary
        ------------------------------------------------------------------
        tick(10);
        report "Pixel backpressure cycles (prog_full engaged): " & to_string(bp_cycles);
        report "Worst angle diff across all frames: " & to_string(chk_max_diff);
        assert v_serr = 0 and chk_errors = 0
            report "TOP_TB: TEST FAILED (" & to_string(v_serr) & " sequencer + " &
                   to_string(chk_errors) & " checker errors)"
            severity failure;
        if G_STALL_TEST then
            report "TOP_TB: ALL TESTS PASSED (stall configuration)" severity note;
        else
            report "TOP_TB: ALL TESTS PASSED (production configuration)" severity note;
        end if;
        sim_done <= true;
        wait;
    end process;

    -- ============================================================
    -- Watchdog: generous bound on the whole run; stall mode gets 10x.
    -- ============================================================
    watchdog : process
        constant BASE_CYCLES    : natural :=
            F1_WIDTH * F1_HEIGHT + 3 * F2_WIDTH * F2_HEIGHT
            + F3_WIDTH * F3_HEIGHT + F3_N_EXPECTED * 80 + 8 * 512 + 150_000;
        constant TIMEOUT_CYCLES : natural := BASE_CYCLES * pick(G_STALL_TEST, 10, 1);
    begin
        wait for TIMEOUT_CYCLES * CLK_PERIOD;
        if not sim_done then
            report "WATCHDOG TIMEOUT: sequence incomplete (drop, deadlock, or " &
                   "missing sentinel/done)" severity failure;
        end if;
        wait;
    end process;

end architecture;
